INSERT INTO vocabularies (topic_id, word, reading, meaning_vi, part_of_speech, jlpt_level_id, example_sentence, example_reading, example_meaning_vi, display_order, is_published, version) VALUES
(147, '一家', 'いっか', 'Một nhà, cả nhà, cả gia đình', 'số từ/lượng từ', 4, 'これは一家です。', 'これはいっかです。', 'Đây là Một nhà, cả nhà, cả gia đình.', 1, TRUE, 1),
(147, 'ありがたい', 'ありがたい', 'Biết ơn, hạnh phúc, đáng quý', 'động từ', 4, '毎日ありがたい。', 'まいにちありがたいします。', 'Hằng ngày tôi biết ơn, hạnh phúc, đáng quý.', 2, TRUE, 1),
(147, '向き合う', 'むきあう', 'Đối diện, đối mặt', 'danh từ/cụm danh từ', 4, 'これは向き合うです。', 'これはむきあうです。', 'Đây là Đối diện, đối mặt.', 3, TRUE, 1),
(147, 'つくづく[と]', 'つくづくと', 'Sâu sắc, tỉ mỉ, thấm thía', 'mẫu câu/cụm từ', 4, '「つくづく[と]」を使います。', '「つくづくと」をつかいます。', 'Tôi dùng mẫu/từ "つくづく[と]" với nghĩa: Sâu sắc, tỉ mỉ, thấm thía.', 4, TRUE, 1),
(147, '養う', 'やしなう', 'Nuôi, nuôi dưỡng', 'danh từ/cụm danh từ', 4, 'これは養うです。', 'これはやしなうです。', 'Đây là Nuôi, nuôi dưỡng.', 5, TRUE, 1),
(147, '役目', 'やくめ', 'Trách nhiệm, vai trò, nhiệm vụ', 'danh từ/cụm danh từ', 4, 'これは役目です。', 'これはやくめです。', 'Đây là Trách nhiệm, vai trò, nhiệm vụ.', 6, TRUE, 1),
(147, '甘える', 'あまえる', 'Làm nũng, nhõng nhẽo', 'động từ', 4, '毎日甘えます。', 'まいにちあまえます。', 'Hằng ngày tôi làm nũng, nhõng nhẽo.', 7, TRUE, 1),
(147, '世間知らず', 'せけんしらず', 'Khờ khạo, ngây thơ', 'danh từ/cụm danh từ', 4, 'これは世間知らずです。', 'これはせけんしらずです。', 'Đây là Khờ khạo, ngây thơ.', 8, TRUE, 1),
(147, 'しつけ', 'しつけ', 'Sự dạy dỗ, việc giáo dục (khuôn phép, nề nếp)', 'danh từ/cụm danh từ', 4, 'これはしつけです。', 'これはしつけです。', 'Đây là Sự dạy dỗ, việc giáo dục (khuôn phép, nề nếp).', 9, TRUE, 1),
(147, '言いつける', 'いいつける', 'Méc, mách', 'danh từ/cụm danh từ', 4, 'これは言いつけるです。', 'これはいいつけるです。', 'Đây là Méc, mách.', 10, TRUE, 1),
(147, '自立（する）', 'じりつ＜する＞', 'Tự lập', 'danh từ/động từ suru', 4, '毎日自立します。', 'まいにちじりつ＜する＞します。', 'Hằng ngày tôi tự lập.', 11, TRUE, 1),
