(147, '意思', 'いし', 'Ý chí, ý muốn', 'danh từ/cụm danh từ', 4, 'これは意思です。', 'これはいしです。', 'Đây là Ý chí, ý muốn.', 13, TRUE, 1),
(147, '尊重（する）', 'そんちょう＜する＞', 'Sự tôn trọng', 'danh từ/động từ suru', 4, '毎日尊重します。', 'まいにちそんちょう＜する＞します。', 'Hằng ngày tôi sự tôn trọng.', 14, TRUE, 1),
(147, '説得（する）', 'せっとく＜する＞', 'Sự thuyết phục', 'danh từ/động từ suru', 4, '毎日説得します。', 'まいにちせっとく＜する＞します。', 'Hằng ngày tôi sự thuyết phục.', 15, TRUE, 1),
